from pathlib import Path
import json,math
from PIL import Image,ImageDraw
P=Path(__file__).resolve().parent;R=P.parent.parent;O=R/'output/bill-carry-cardinal-natural-v1'
d=json.loads((O/'journeys.json').read_text());v=json.loads((O/'validation.json').read_text());assert v['passed'] and d['failures']==0
for j in d['journeys']:
 gear='helmet' if j['helmet'] else 'bare';rows=j['captures'];b=Image.new('RGB',(960,240*math.ceil(len(rows)/6)),'#22343e');dr=ImageDraw.Draw(b)
 for i,c in enumerate(rows):
  x0=i%6*160;y0=i//6*240;room=Image.open(O/c['room']).convert('RGB');x=255+(c['foot'][0]-7680)*398/384;y=287+(c['foot'][1]-8064)*398/384;b.paste(room.crop((round(x)-75,round(y)-130,round(x)+75,round(y)+35)),(x0+5,y0));src=Image.open(O/c['source']).convert('RGBA');s=82/148;src=src.resize((round(src.width*s),round(src.height*s)),Image.Resampling.LANCZOS);b.paste(src,(round(x0+80-128*s),round(y0+225-224*s)),src);dr.text((x0+3,y0+225),str(round(c['time'],2))+'s '+c['direction']+(' entry' if c['starting'] else ''),fill='white')
 b.save(P/(gear+'-natural-review.png'))
html='''<!doctype html><meta charset="utf-8"><title>Bill — natural workshop carrying</title><style>body{font:16px system-ui;background:#182932;color:#dde8e9;margin:24px}canvas,img{max-width:100%;background:#22343e}button{margin:10px}</style><h1>Bill — natural workshop carrying</h1><p>The workshop chooses its own route. These are the actual submitted sources replayed at recorded timestamps and a fixed review pivot.</p><button id="play">Pause</button><label>Size <select id="size"><option>82</option><option>148</option></select></label><p id="clock"></p><h2>Bare / helmet</h2><canvas width="480" height="270"></canvas><p>Room boards pair the actual frame with its source below. This reveals arrival changes as well as pickup and walking; the final North stow transition remains under review.</p><h2>Bare · actual route</h2><img src="bare-natural-review.png"><h2>Helmet · actual route</h2><img src="helmet-natural-review.png"><script>const data=DATA,images=new Map(),folder='../../output/bill-carry-cardinal-natural-v1/';for(const j of data.journeys)for(const r of j.records)if(!images.has(r.source)){const im=new Image();im.src=folder+r.source;images.set(r.source,im)}let time=0,last=performance.now(),playing=true;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};function draw(now){if(playing)time+=(now-last)/1000;last=now;const ctx=document.querySelector('canvas').getContext('2d'),s=Number(document.querySelector('#size').value)/148;ctx.clearRect(0,0,480,270);data.journeys.forEach((j,col)=>{const t=time%(j.records.at(-1).time+.5),r=j.records.findLast(r=>r.time<=t)||j.records[0],im=images.get(r.source);if(im.complete&&im.naturalWidth)ctx.drawImage(im,120+col*240-128*s,240-224*s,256*s,256*s)});document.querySelector('#clock').textContent='Actual recorded source sequence';requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>'''
(P/'index.html').write_text(html.replace('DATA',json.dumps(d)),encoding='utf-8');(P/'runtime-evidence.json').write_text(json.dumps({'validation':v,'checks':d['checks'],'scope':d['scope'],'headless':json.loads((R/'output/bill-carry-cardinal-player-v1/validation.json').read_text()),'normalSelectionChanged':False,'nativeSourceSamples':sum(len(j['captures']) for j in d['journeys'])},indent=2)+'\n');print('Saved natural-route boards and recorded source clock')
